  "Sobrevive a las hordas con tu compañero Pokémon · gratis, en PC y móvil": "與寶可夢夥伴一起迎戰大軍 · 電腦與手機皆可免費遊玩",
  "Juego de supervivencia con Pokémon, gratis en el navegador y en el móvil.": "免費的寶可夢生存遊戲，打開瀏覽器就能玩。",
