  "Juego de fans {x}: sin anuncios ni pagos. Pokémon y sus personajes son propiedad de Nintendo, Creatures y GAME FREAK; este proyecto no está afiliado a ellos.": "本作為{x}的同人遊戲，沒有廣告或付費項目。寶可夢及相關角色屬於 Nintendo、Creatures 與 GAME FREAK，本專案與上述公司無關。",
  ": sin anuncios ni pagos. Pokémon y sus personajes son propiedad de Nintendo, Creatures y GAME FREAK; este proyecto no está afiliado a ellos.": "，沒有廣告或付費項目。寶可夢及相關角色屬於 Nintendo、Creatures 與 GAME FREAK，本專案與上述公司無關。",
