  "×1,8 daño, +2 minas y explosión más grande": "傷害 ×1.8、陷阱數量 +2，爆炸範圍擴大",
  "×1,7 daño, +2 meteoros y más radio": "傷害 ×1.7、流星數量 +2，半徑增加",
  "×1,8 daño, +1 a la vez y dispara más rápido": "傷害 ×1.8、同時存在的數量 +1，射擊速度提升",
  "×1,9 daño, más distancia y menos recarga": "傷害 ×1.9、衝刺距離增加，冷卻時間縮短",
  "×1,8 daño, charcos más grandes y duraderos": "傷害 ×1.8，地面效果範圍擴大、持續時間延長",
  "×1,7 daño, +4 disparos y +1 perforación": "傷害 ×1.7、發射數量 +4、穿透次數 +1",
  "¡Horda de tipo {x}!": "{x}屬性大軍來襲！",
  "¡Hora dorada! Doble de experiencia": "黃金時刻！獲得的經驗加倍",
  "¡Un {x} se ha perdido! Búscalo y llévalo a la marca": "{x}迷路了！找到牠，帶牠前往標記處",
  "¡{x} te sigue! Llévalo a la marca verde": "{x}正在跟著你！帶牠前往綠色標記處",
  "¡{x} se ha asustado y ha huido…!": "{x}受到驚嚇，逃走了！",
  "{x} se ha cansado de esperar y se ha ido…": "{x}等得不耐煩，離開了…",
  "¡Has llevado a {x} a casa! Te lo agradece": "成功帶{x}回家！牠向你表達謝意",
  "¡{x} se une a tu equipo!": "{x}加入了你的隊伍！",
  "¡{x} te da las gracias! (+150 monedas, ya lo tenías)": "{x}向你道謝！（已擁有這隻寶可夢，獲得 150 寶可幣）",
  "¡Un {x} con un ticket ×10! ¡Atrápalo antes de que huya!": "{x}帶著十連券！快在牠逃走前追上牠！",
  "¡Un {x} cargado de monedas! ¡Atrápalo antes de que huya!": "{x}帶著大量寶可幣！快在牠逃走前追上牠！",
  "¡{x} se ha escapado!": "{x}逃走了！",
  "HORA DORADA · {x} s": "黃金時刻 · 剩餘 {x} 秒",
  "HORDA {x} · {x} s": "{x}屬性大軍 · 剩餘 {x} 秒",
  "Marca · {x} m": "標記 · 距離 {x} 公尺",
  "¿Te está gustando PokéSurvivor? Lo hago yo solo y los servidores cuestan dinero. Si quieres, puedes ayudarme a mantenerlo en línea.": "喜歡 PokéSurvivor 嗎？原作者獨力開發遊戲，也需要負擔伺服器費用。你可以自願贊助，支持原作持續營運。",
  "Apoyar en Ko-fi": "透過 Ko-fi 支持原作者",
  "Entrar con Google (si ya tienes cuenta)": "使用 Google 登入既有帳號",
  "Este mes se han llenado las plazas de cuentas nuevas: vuelven el 1 de {x}. Si ya tienes cuenta, entra normal. Si no, juega como invitado.": "本月的註冊名額已滿，預計 {x} 月 1 日重新開放。已有帳號可照常登入，也可以先以訪客身分遊玩。",
  "Este mes ya no quedan plazas para cuentas nuevas (vuelven el 1 de {x}). Mientras, puedes jugar como invitado.": "本月已無註冊名額，預計 {x} 月 1 日重新開放。這段期間仍可使用訪客模式。",
  "El juego ha fallado: tu partida se ha guardado hasta aquí": "遊戲發生錯誤，已保留截至目前為止的進度",
  "Pausa: esperando a {x} (anfitrión)…": "暫停中：正在等待房主{x}…",
  "Novedades": "更新紀錄",
  "Hay una versión nueva del juego: actualizando en {x} s…": "遊戲有新版本，將於 {x} 秒後更新…",
  "Actualización obligatoria: tu partida se guarda y el juego se recarga en {x} s…": "此更新必須套用。將保存進度，並於 {x} 秒後重新載入…",
  "No se pudo conectar (reintentando…)": "無法建立連線，正在重試…",
  "No se puede conectar con algún amigo: su red (o la tuya) no deja jugar en grupo. Probad con otra wifi o datos móviles; se reintenta solo.": "無法與其中一位好友連線，可能是任一方的網路限制所致。請嘗試其他 Wi-Fi 或行動網路，系統也會自動重試。",
  "Ahora mismo no se pueden crear cuentas nuevas. Si ya tienes cuenta, entra normal; si no, puedes jugar como invitado.": "目前暫停開放註冊。已有帳號可照常登入，也可以先以訪客身分遊玩。",
  "Atajos de movimientos": "固定招式欄位",
  "Elige qué movimiento va siempre en cada hueco (teclas 1-4 o los iconos de abajo), para la memoria muscular. Si aún no tienes tantos movimientos, va al hueco más cercano.": "指定每個欄位要放的招式，方便使用 1～4 或畫面按鈕切換。若目前招式數量不足，會放到最接近的可用欄位。",
  "Golpe Crítico": "會心一擊",
  "+3% de críticos (x1,5 de daño)": "會心率 +3%（傷害為 1.5 倍）",
  "Cambio de cartas": "重抽卡片",
  "+1 cambio de cartas de nivel por run": "每場冒險可重抽升級卡片的次數 +1",
  "Veto": "排除招式",
  "Bloquea 1 movimiento: no te sale en las cartas": "排除一個招式，使其不再出現在升級卡片中",
  "Elegir ({x})": "選擇（{x}）",
  "Toca los movimientos que no quieres que te salgan en las cartas ({x}). El movimiento de inicio no se puede vetar.": "點選要從升級卡片中排除的招式（{x}）。初始招式無法排除。",
  "Ya tienes {x} vetados: quita uno primero": "已排除 {x} 個招式，請先取消其中一個",
  "En iPhone, Safari no deja poner las webs a pantalla completa. Pulsa Compartir y luego \"Añadir a pantalla de inicio\": abriendo el juego desde ese icono se juega a pantalla completa.": "若 iPhone 的 Safari 無法使用全螢幕，請點選「分享」→「加入主畫面」，再從主畫面的圖示開啟遊戲。",
  "Ruinas del Juicio": "制裁遺跡",
  "LA SENTENCIA": "制裁降臨",
  "DE ARCEUS": "阿爾宙斯",
  "El tiempo se ha agotado…": "時間到了…",
  "¡ARCEUS HA DESCENDIDO!": "阿爾宙斯降臨！",
  "Es invencible: huye y aguanta todo lo que puedas": "牠無法被擊敗！快逃，盡可能撐下去",
  "Toca la pantalla para saltar": "點一下螢幕略過",
  "Pulsa Espacio para saltar": "按空白鍵略過",
  "¡Huye de Arceus! Es invencible": "快逃離阿爾宙斯！牠無法被擊敗",
  "¡{x} acude a la Sentencia!": "{x}應召加入制裁！",
  "SENTENCIA · {x} · JEFES {x}": "制裁 · {x} · 頭目 {x}",
