  "Gracias: la revisaremos": "已收到檢舉，我們會進行審查",
  "Vincula tu cuenta de Google para volver a entrar en la misma partida si olvidas tu contraseña.": "綁定 Google 帳號後，即使忘記遊戲密碼，也能使用 Google 登入，繼續原本的進度。",
