  "Es el nombre que verán tus amigos y el que sale en el ranking.": "好友與排行榜會顯示這個暱稱。",
  "Tu apodo y tus marcas son públicos. Tu contraseña y tu correo de Google no se muestran.": "其他玩家可以查看你的暱稱與排行榜成績；密碼與 Google 電子郵件不會公開。",
  "POKé SLOTS": "寶可夢拉霸",
