  "Poder temporal": "祭壇增益",
  "Tipos, clima de daño, órbitas y daño puro se calculan aparte.": "相剋、天氣傷害、軌道冷卻及純粹傷害另計。",
  "Favoritos, fuente y bonificaciones": "最愛收藏、字型與能力加成",
  "Marca hasta 100 Pokémon como favoritos con dos pulsaciones rápidas; filtra tu colección con el corazón.": "快速點兩下寶可夢即可加入或取消最愛，上限 100 隻；可用左側最愛篩選跨地區查看。",
  "Elige Cubic 11 en Ajustes y consulta tus bonificaciones durante la partida y al elegir cartas.": "可在設定切換 Cubic 11 像素字型，並在遊戲角落及選卡畫面查看累計能力加成。",
  "La barra de vida bajo el personaje se ha bajado un poco para evitar las animaciones de ataque.": "角色下方的血條再向下移動一些，減少與攻擊動畫重疊。",
  "Ninguno": "無",
  "Reserva activada": "招式儲備：開啟",
  "Reserva desactivada": "招式儲備：關閉",
  "No equipar": "不裝備",
  "Equipar": "裝備",
  "Seguir sin objeto equipado.": "維持未裝備道具的狀態。",
  "Nombres dorados y decisiones de equipo": "金色紀念名稱與裝備選擇",
  "Los Pokémon que sobreviven 30 minutos lucen un nombre dorado con destellos.": "存活達 30 分鐘的寶可夢，名稱改為金字、金框與閃光效果。",
  "Tras comprar Repertorio puedes activar o desactivar el segundo movimiento inicial para cada Pokémon.": "購買招式儲備後，可為每隻寶可夢切換是否攜帶第二個初始招式。",
  "El primer objeto también te pregunta si quieres equiparlo.": "首次拾取道具時也會詢問是否裝備，不再自動裝備。",
  "No se pudo cambiar la reserva.": "無法變更招式儲備設定，請重新開啟強化頁面再試。",
  "Sanadores reforzados y shiny al 3%": "治療者調整與抽卡異色 3%",
  "Los sanadores curan del 5 al 12% según el nivel; cada objetivo recibe curación como máximo una vez cada 3 segundos.": "治療者依玩家等級回復 5～12%；同一目標每 3 秒最多接受一次治療。",
  "Los sanadores pueden curarse entre sí y a enemigos especiales, atraviesan paredes y aparecen tras el primer minuto, hasta 10 a la vez.": "治療者可互補、替特殊敵人回血並穿牆治療；開場一分鐘後可生成，場上最多 10 隻。",
  "La probabilidad shiny del gacha sube al 3%; las probabilidades de estrellas y las garantías no cambian.": "抽卡異色獨立機率提高至 3%，不改星級機率與保底。",
  "Límite actual": "目前達減傷上限",
  "Cubic 11:": "Cubic 11：",
  "· SIL Open Font License 1.1.": "· SIL Open Font License 1.1 授權。",
  "Armadura corregida y escudos reforzados": "護甲修正與護盾者調整",
  "La armadura, los objetos y los efectos temporales ya no se restan entre sí; la reducción total, incluido el cuerpo a cuerpo, tiene un máximo del 90%.": "護甲、道具與臨時效果分開計算，避免互相倒扣；含近戰保護的防禦減傷最高 90%。",
  "Los protectores dan escudos del 10 al 40% según el nivel, sin autoescudo; cada objetivo sólo recibe un escudo cada 2,5 segundos.": "護盾者依玩家等級提供 10～40% 護盾，不能替自己上盾；同一目標每 2.5 秒最多接受一次上盾。",
  "Sanadores y protectores tienen un límite de 25 de cada tipo. Cubic 11 es la fuente predeterminada para nuevos ajustes.": "治療者與護盾者各最多 25 隻；未設定過字型的玩家預設使用 Cubic 11。",
  "El interruptor de Repertorio aparece en una fila aparte; al comprarlo desaparece el indicador de nivel máximo.": "招式儲備開關改至獨立下一行，購買後不再顯示已達上限與單格進度點。",
  "Los nombres conmemorativos muestran el marco dorado y los destellos con más claridad en la selección de Pokémon.": "寶可夢選擇畫面的紀念名稱金框與閃光更清楚，遊戲 HUD 也保留呈現。",
  "Los nombres conmemorativos conservan el texto dorado y los destellos, sin marco.": "紀念名稱移除外框與底色，保留金字及閃光。",
  "Texto dorado sin marco": "金字閃光保留、移除外框",
  "Una vez cada 24 horas. El apodo anterior queda reservado durante 7 días.": "每 24 小時可修改一次，舊暱稱保留 7 天。",
  "Nuevo apodo": "新暱稱",
  "Cambiar apodo": "修改暱稱",
