  "Marker · {x} m": "標記 · 距離 {x} 公尺",
  "Enjoying PokéSurvivor? I make it on my own and the servers cost money. If you'd like, you can help keep it online.": "喜歡 PokéSurvivor 嗎？原作者獨力開發遊戲，也需要負擔伺服器費用。你可以自願贊助，支持原作持續營運。",
  "Support on Ko-fi": "透過 Ko-fi 支持原作者",
  "Sign in with Google (if you already have an account)": "使用 Google 登入既有帳號",
  "New accounts are full for this month: they reopen on {x} 1. If you already have an account, sign in as usual. If not, play as a guest.": "本月的註冊名額已滿，預計 {x} 月 1 日重新開放。已有帳號可照常登入，也可以先以訪客身分遊玩。",
  "There are no new account slots left this month (they reopen on {x} 1). Meanwhile, you can play as a guest.": "本月已無註冊名額，預計 {x} 月 1 日重新開放。這段期間仍可使用訪客模式。",
  "The game crashed: your run has been saved up to this point": "遊戲發生錯誤，已保留截至目前為止的進度",
  "Paused: waiting for {x} (host)…": "暫停中：正在等待房主{x}…",
  "What's new": "更新紀錄",
  "A new version of the game is out: updating in {x} s…": "遊戲有新版本，將於 {x} 秒後更新…",
  "Required update: your run is saved and the game reloads in {x} s…": "此更新必須套用。將保存進度，並於 {x} 秒後重新載入…",
  "Could not connect (retrying…)": "無法建立連線，正在重試…",
  "Can't connect to one of your friends: their network (or yours) doesn't allow group play. Try another Wi-Fi or mobile data; it retries automatically.": "無法與其中一位好友連線，可能是任一方的網路限制所致。請嘗試其他 Wi-Fi 或行動網路，系統也會自動重試。",
  "New accounts cannot be created right now. If you already have an account, sign in as usual; otherwise, you can play as a guest.": "目前暫停開放註冊。已有帳號可照常登入，也可以先以訪客身分遊玩。",
  "Move shortcuts": "固定招式欄位",
  "Choose which move always goes in each slot (keys 1-4 or the icons at the bottom), for muscle memory. If you do not have that many moves yet, it goes to the closest slot.": "指定每個欄位要放的招式，方便使用 1～4 或畫面按鈕切換。若目前招式數量不足，會放到最接近的可用欄位。",
  "Critical Hit": "會心一擊",
  "+3% critical chance (x1.5 damage)": "會心率 +3%（傷害為 1.5 倍）",
  "Card reroll": "重抽卡片",
  "+1 level-up card reroll per run": "每場冒險可重抽升級卡片的次數 +1",
  "Ban": "排除招式",
