  "Choose ({x})": "選擇（{x}）",
  "Tap the moves you do not want in your cards ({x}). The starting move cannot be banned.": "點選要從升級卡片中排除的招式（{x}）。初始招式無法排除。",
  "You already have {x} banned: remove one first": "已排除 {x} 個招式，請先取消其中一個",
  "On iPhone, Safari does not let websites go fullscreen. Tap Share and then \"Add to Home Screen\": opening the game from that icon plays it fullscreen.": "若 iPhone 的 Safari 無法使用全螢幕，請點選「分享」→「加入主畫面」，再從主畫面的圖示開啟遊戲。",
