  "Link my Gmail": "綁定 Google 帳號",
  "Don't ask again": "不再顯示",
  "Gmail linked! If you forget your password, sign in with Google.": "已綁定 Google 帳號。忘記遊戲密碼時，仍可使用 Google 登入。",
  "That Gmail already has its own game account. Use another Gmail.": "這個 Gmail 已連結其他遊戲帳號，請使用另一個 Gmail。",
